      type: 'session.runtimeOwner',
      provider: 'codex',
      sessionId: DIV_SESSION_ID,
      epoch: 1,
      generation: 2,
      ownerKind: 'terminal',
      terminalId: 't-5',
      operationId: 'handoff-div',
